module my_dff_behavioral(clk, d, q, qbar, preset, clr);
	input preset, clr, clk,d;
	output reg q;
	output qbar;
	assign qbar =~q;
	always@( posedged clk or posedge preset or posedge clr)
		if (clr)
			q <=1'b0;
		else if (preset)
			q<=1'b1;
		else 
			q<=d;
endmodule

module my_dff_async(d,clkbar,q,qbar,aclrbar,asetbar);
	input aclrbar,asetbar,d,clkbar;
	output reg q;
	output qbar;
	assign qbar =~q;
	always@(*)
		if(~aclrbar)
			q<=1'b0;
		else if(~asetbar)
			q<=1'b1;
		else if(~clkbar)
			q<=d;
	initial begin q=0; end
endmodule



